Given the root of a binary tree, find the bottom view of the tree as a list of node values in order of increasing horizontal distance(HD).The root has HD = 0.The left child decreases HD by 1, and the right child increases HD by 1.If  multiple nodes share the same HD and depth, select the node that appears later in level-order traversal.Return the values of these nodes from the leftmost to the rightmost horizontal distance.Examples:Input: Output: [4, 2, 5, 3, 6]Explanation:  Input:  Output: [5, 10, 4, 28, 25]Explanation: Here, 14 and 28 both have horizontal distance = 1 from root, but we are taking 28 in our answer as 28 appears later in the level order traversal. Try It YourselfTable of Content[Expected Approach - 1] Using DFS - O(n) Time and O(n) Space[Expected Approach - 2] Using BFS- O(n) Time and O(n) Space[Expected Approach - 1] Using DFS - O(n) Time and O(n) SpaceThe idea is to create a hashmap to store the horizontal distance and the bottom-most node having that horizontal distance wrt root node.During DFS, if we encounter a node whose horizontal distance is not present in the map, add it to the map. If we encounter a node whose horizontal distance already exists as a key in the map:Choose the node with greater depth.If both nodes have the same depth, choose the current node, because it appears later in level order traversal.
            C++

    #include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

// Node Structure
class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int x) {
        data = x;
        left = right = NULL;
    }
};


int minHD, maxHD;

// DFS function to fill hdMap with bottom-most
// nodes at each horizontal distance
void dfs(Node* root, int hd, int depth, unordered_map<int, pair<int, int>>& hdMap) {
    if (root == NULL) return;

    minHD = min(minHD, hd);
    maxHD = max(maxHD, hd);

    // If this horizontal distance is 
    // being visited for the first time or
    // we're at a deeper level, update it
    if (hdMap.find(hd) == hdMap.end() || depth >= hdMap[hd].second) {
        hdMap[hd] = {root->data, depth};
    }

    dfs(root->left, hd - 1, depth + 1, hdMap);
    dfs(root->right, hd + 1, depth + 1, hdMap);
}

// Returns the bottom view of a binary tree
vector<int> bottomView(Node* root) {
    if (root == NULL) return {};

    minHD=0, maxHD=0;

    // Map to store the last node's data and its depth
    // at each horizontal distance
    unordered_map<int, pair<int,int>> hdMap;

    dfs(root, 0, 0, hdMap);

    vector<int> result;

    // Iterate through horizontal distances
    // in range from min HD to max HD
    for (int hd = minHD; hd <= maxHD; hd++) {
        result.push_back(hdMap[hd].first);
    }

    return result;
}

int main() {
    // Create binary tree
    //       20
    //      /  \
    //    8     22
    //   / \     \
    //  5   3     25
    //     / \    /
    //    10 14  28

    Node* root = new Node(20);
    root->left = new Node(8);
    root->right = new Node(22);
    root->left->left = new Node(5);
    root->left->right = new Node(3);
    root->right->left = new Node(4);
    root->left->right->left = new Node(10);
    root->left->right->right = new Node(14);
    root->right->right = new Node(25);
    root->right->right->left = new Node(28);

    minHD = 0; maxHD = 0;

    vector<int> result = bottomView(root);

    for (int val : result) {
        cout << val << " ";
    }
}


